import React from "react";
import { Link } from "react-router-dom";

function Home() {
  return (
    <div className="bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen flex flex-col justify-center items-center text-center text-white px-6">
      <h2 className="text-4xl md:text-5xl font-extrabold mb-6 drop-shadow-lg">
        Welcome to the Food Truck Vendor Application 🚚✨
      </h2>
      <p className="max-w-2xl mb-6 text-lg md:text-xl">
        Discover the best food trucks in Chennai & Bangalore!  
        Join our community of skilled vendors and connect with food lovers eager to explore street food.
      </p>
      <Link
        to="/apply"
        className="bg-yellow-400 text-gray-900 font-semibold px-6 py-3 rounded-full shadow-lg hover:bg-yellow-500 transition"
      >
        Become a Vendor
      </Link>
    </div>
  );
}

export default Home;
